CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE role_name AS ENUM ('operator_opd','organisasi','validator_data','validator_aplikasi','validator_infrastruktur','validator_keamanan','admin','pimpinan','superadmin');
CREATE TYPE submission_status AS ENUM ('draft','submitted','approved','rejected','archived');
CREATE TYPE roadmap_status AS ENUM ('belum_mulai','berjalan','selesai');
CREATE TABLE architecture_periods (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE, start_year int NOT NULL, end_year int NOT NULL, is_active boolean DEFAULT false, created_at timestamptz DEFAULT now());
CREATE TABLE opd (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text UNIQUE NOT NULL, active boolean DEFAULT true);
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, role role_name NOT NULL, opd_id uuid REFERENCES opd(id), active boolean DEFAULT true, created_at timestamptz DEFAULT now());
CREATE TABLE ral_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, level int NOT NULL, parent_id uuid REFERENCES ral_references(id));
CREATE TABLE rab_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, level int NOT NULL, parent_id uuid REFERENCES rab_references(id));
CREATE TABLE process_businesses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, opd_id uuid REFERENCES opd(id), period_id uuid REFERENCES architecture_periods(id), status submission_status DEFAULT 'approved');
CREATE TABLE services (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, name text NOT NULL, purpose text, function_name text, opd_id uuid NOT NULL REFERENCES opd(id), period_id uuid NOT NULL REFERENCES architecture_periods(id), ral_id uuid REFERENCES ral_references(id), rab_id uuid REFERENCES rab_references(id), method text, target text, benefit text, economic_potential text, risk text, mitigation text, status submission_status DEFAULT 'draft', submitted_by uuid REFERENCES users(id), approved_by uuid REFERENCES users(id), approved_at timestamptz, created_at timestamptz DEFAULT now(), updated_at timestamptz DEFAULT now());
CREATE TABLE service_process_businesses (service_id uuid REFERENCES services(id) ON DELETE CASCADE, process_business_id uuid REFERENCES process_businesses(id), PRIMARY KEY(service_id,process_business_id));
CREATE TABLE validation_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid REFERENCES services(id) ON DELETE CASCADE, actor_id uuid REFERENCES users(id), from_status submission_status, to_status submission_status NOT NULL, note text, created_at timestamptz DEFAULT now());
CREATE TABLE gap_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), service_id uuid REFERENCES services(id) ON DELETE CASCADE, category text NOT NULL, finding text NOT NULL, priority text NOT NULL, status text DEFAULT 'open', created_at timestamptz DEFAULT now());
CREATE TABLE roadmap_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), period_id uuid REFERENCES architecture_periods(id), service_id uuid REFERENCES services(id), gap_id uuid REFERENCES gap_analyses(id), year int NOT NULL, title text NOT NULL, target text, status roadmap_status DEFAULT 'belum_mulai', evaluation_note text, follow_up text, created_at timestamptz DEFAULT now());
